using ClinixMX.Data;
namespace ClinixMX;
public sealed class MainForm:Form
{
 readonly ClinixDb db=new(); readonly TextBox search=new(); readonly DataGridView grid=new();
 public MainForm(){Text="Clinix MX — Expediente clínico";Width=1200;Height=760;StartPosition=FormStartPosition.CenterScreen;BackColor=Color.White;
 var header=new Panel{Dock=DockStyle.Top,Height=70,BackColor=Color.FromArgb(18,91,94)};header.Controls.Add(new Label{Text="CLINIX MX",ForeColor=Color.White,Font=new Font("Segoe UI",20,FontStyle.Bold),Left=24,Top=18,AutoSize=true});
 search.Left=220;search.Top=18;search.Width=360;search.PlaceholderText="Buscar paciente...";header.Controls.Add(search);var add=new Button{Text="+ Nuevo paciente",Left=600,Top=17,Width=150,Height=36};add.Click+=(_,_)=>AddPatient();header.Controls.Add(add);var backup=new Button{Text="Backup",Left=760,Top=17,Width=100,Height=36};backup.Click+=(_,_)=>MessageBox.Show("Backup creado en Documentos\\ClinixMX-Backups");header.Controls.Add(backup);Controls.Add(header);
 grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AutoGenerateColumns=true;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;Controls.Add(grid);search.TextChanged+=(_,_)=>RefreshPatients();Load+=(_,_)=>RefreshPatients();}
 void RefreshPatients(){grid.DataSource=db.SearchPatients(search.Text).Select(x=>new{Id=x.Id,Paciente=x.Name,Telefono=x.Phone}).ToList();}
 void AddPatient(){using var f=new Form{Text="Nuevo paciente",Width=600,Height=620,StartPosition=FormStartPosition.CenterParent};var fields=new Dictionary<string,TextBox>();int y=20;foreach(var n in new[]{"Nombre completo","Fecha de nacimiento","Sexo","Teléfono","Email","Domicilio","Contacto de emergencia","Alergias","Antecedentes","Medicamentos","Grupo sanguíneo"}){f.Controls.Add(new Label{Text=n,Left=20,Top=y+4,Width=180});var t=new TextBox{Left=210,Top=y,Width=340};if(n is "Alergias" or "Antecedentes" or "Medicamentos"){t.Height=55;t.Multiline=true;}f.Controls.Add(t);fields[n]=t;y+=50+(t.Multiline?15:0);}var save=new Button{Text="Guardar paciente",Left=210,Top=Math.Min(y,520),Width=180,Height=38};save.Click+=(_,_)=>{if(string.IsNullOrWhiteSpace(fields["Nombre completo"].Text)){MessageBox.Show("El nombre es obligatorio.");return;}db.AddPatient(fields["Nombre completo"].Text,fields["Fecha de nacimiento"].Text,fields["Sexo"].Text,fields["Teléfono"].Text,fields["Email"].Text,fields["Domicilio"].Text,fields["Contacto de emergencia"].Text,fields["Alergias"].Text,fields["Antecedentes"].Text,fields["Medicamentos"].Text,fields["Grupo sanguíneo"].Text);f.DialogResult=DialogResult.OK;};f.Controls.Add(save);f.ShowDialog(this);RefreshPatients();}
}